 'end':['lõpp','fin','Ende'],
 'Activity':['Tegevus','Activité','Aktivität'],
 'Start event':['Algussündmus','Événement de début','Startereignis'],
 'End event':['Lõppsündmus','Événement de fin','Endereignis'],
