export function translate(locale,key,values={}) {
 const singular={'{count} steps':'{count} step','{count} system cards need clarification':'{count} system card needs clarification','{count} words':'{count} word','{count} activities':'{count} activity','{count} roles':'{count} role','{count} questions before approval':'{count} question before approval'};
 if(values.count===1&&singular[key])key=singular[key];
 const index={et:0,fr:1,de:2}[normalizeLocale(locale)];
 const text=index===undefined?key:TRANSLATIONS[key]?.[index]||key;
 return String(text).replace(/\{(\w+)\}/g,(match,name)=>Object.hasOwn(values,name)?String(values[name]):match);
}

export function translatedSummary(locale,summary='') {
 summary=typeof summary==='string'?summary:'';
 for(const [prefix,key,param] of [['Loaded prepared sample: ','Loaded prepared sample: {name}','name'],['Restored version ','Restored version {version}','version'],['Answered: ','Answered: {question}','question']]) {
  if(summary.startsWith(prefix))return translate(locale,key,{[param]:param==='name'?translate(locale,summary.slice(prefix.length)):summary.slice(prefix.length)});
 }
 return translate(locale,summary);
}

